//! The bundled word list (`words.txt`, generated by `tools/build_words.py`).
//!
//! The file is front-coded: one word per line, sorted bytewise, each line
//! being `<P><suffix>` where `P` is one character giving how many leading
//! characters the word shares with the previous one (`0`-`9` for 0-9, `A`-`Z`
//! for 10-35). `\r\n` line ends are accepted too, in case a checkout converted
//! them. The file stays in the binary as is. At first use it is indexed once:
//! every [`RESTART`]-th word is kept for binary-searched lookups, and each
//! line's shared length and suffix position are kept in flat arrays so that
//! suggestion walks skip whole subtrees with a scan over one byte per word
//! (one byte per [`BLOCK`] words across large subtrees).

use std::sync::OnceLock;

use crate::distance::WordSource;

static WORDS: &str = include_str!("words.txt");

/// Distance (in words) between two entries of the restart index.
const RESTART: usize = 32;
/// Number of words summarised by one entry of `Bundled::block_min`.
const BLOCK: usize = 64;
/// Bundled words are 2..=20 lowercase ASCII letters.
pub(crate) const MAX_WORD_LEN: usize = 20;

pub(crate) struct Bundled {
    /// The front-coded list.
    text: &'static str,
    /// Every `RESTART`-th word, with the byte offset of the line after it.
    restarts: Vec<(Box<str>, usize)>,
    /// Per word: chars shared with the previous word…
    shared: Vec<u8>,
    /// …and the byte range of the rest of the word in `text`.
    rest_start: Vec<u32>,
    rest_len: Vec<u8>,
    /// The minimum of `shared` over each run of `BLOCK` words.
    block_min: Vec<u8>,
}

/// The indexed bundled list (built once, on first use).
pub(crate) fn bundled() -> &'static Bundled {
    static BUNDLED: OnceLock<Bundled> = OnceLock::new();
    BUNDLED.get_or_init(|| Bundled::new(WORDS))
}

fn prefix_len(code: u8) -> usize {
    match code {
        b'0'..=b'9' => usize::from(code - b'0'),
        b'A'..=b'Z' => usize::from(code - b'A') + 10,
        _ => 0,
    }
}

/// The `(shared prefix length, suffix)` lines of a front-coded list,
/// starting at byte offset `pos`.
struct Lines {
    text: &'static str,
    pos: usize,
}

impl Iterator for Lines {
    /// `(shared prefix length, suffix, byte offset of the suffix)`.
    type Item = (usize, &'static str, usize);

    fn next(&mut self) -> Option<Self::Item> {
        loop {
            let start = self.pos;
            let rest = self.text.get(start..).filter(|r| !r.is_empty())?;
            let end = rest.find('\n').unwrap_or(rest.len());
            self.pos += end + 1;
            let line = &rest[..end];
            let line = line.strip_suffix('\r').unwrap_or(line);
            if let (Some(&code), Some(suffix)) = (line.as_bytes().first(), line.get(1..)) {
                return Some((prefix_len(code), suffix, start + 1));
            }
        }
    }
}

impl Bundled {
    fn new(text: &'static str) -> Self {
        let estimate = text.len() / 4;
        let mut restarts = Vec::with_capacity(estimate / RESTART);
        let (mut shared, mut rest_start, mut rest_len) = (
            Vec::with_capacity(estimate),
            Vec::with_capacity(estimate),
            Vec::with_capacity(estimate),
        );
        let mut word = String::with_capacity(MAX_WORD_LEN);
        let mut lines = Lines { text, pos: 0 };
        while let Some((common, suffix, offset)) = lines.next() {
            // Clamp malformed lines so that every entry stays within the
            // limits that lookups rely on.
            let common = common.min(word.len());
            let suffix = &suffix[..suffix.len().min(MAX_WORD_LEN - common)];
            word.truncate(common);
            word.push_str(suffix);
            if shared.len().is_multiple_of(RESTART) {
                restarts.push((word.clone().into_boxed_str(), lines.pos));
            }
            shared.push(common as u8);
            rest_start.push(offset as u32);
            rest_len.push(suffix.len() as u8);
        }
        let block_min = shared
            .chunks(BLOCK)
            .map(|block| block.iter().copied().min().unwrap_or(0))
            .collect();
        Self {
            text,
            restarts,
            shared,
            rest_start,
            rest_len,
            block_min,
        }
    }

    /// A cursor over all words, for [`crate::distance::TrieWalker::walk`].
    pub(crate) fn cursor(&self) -> Cursor<'_> {
        Cursor {
            list: self,
            next: 0,
        }
    }

    /// Exact lookup of a lowercase word.
    pub(crate) fn contains(&self, word: &str) -> bool {
        if word.len() > MAX_WORD_LEN || !word.bytes().all(|b| b.is_ascii_lowercase()) {
            return false;
        }
        let target = word.as_bytes();
        let block = self
            .restarts
            .partition_point(|(first, _)| first.as_bytes() <= target);
        let Some((first, next)) = block.checked_sub(1).map(|i| &self.restarts[i]) else {
            return false;
        };
        if first.as_bytes() == target {
            return true;
        }
        let mut buf = [0u8; MAX_WORD_LEN];
        let mut len = first.len();
        buf[..len].copy_from_slice(first.as_bytes());
        for (shared, suffix, _) in (Lines {
            text: self.text,
            pos: *next,
        })
        .take(RESTART - 1)
        {
            let suffix = suffix.as_bytes();
            if shared > len || shared + suffix.len() > MAX_WORD_LEN {
                return false; // malformed data
            }
            buf[shared..shared + suffix.len()].copy_from_slice(suffix);
            len = shared + suffix.len();
            match buf[..len].cmp(target) {
                std::cmp::Ordering::Less => {}
                std::cmp::Ordering::Equal => return true,
                std::cmp::Ordering::Greater => return false,
            }
        }
        false
    }

    /// Every word, decoded (tests only).
    #[cfg(test)]
    pub(crate) fn words(&self) -> Vec<String> {
        let mut out = Vec::with_capacity(self.shared.len());
        let mut word = String::new();
        let mut cursor = self.cursor();
        while let Some((shared, rest)) = cursor.next_below(usize::MAX) {
            word.truncate(shared);
            word.push_str(rest);
            out.push(word.clone());
        }
        out
    }
}

/// Position in the bundled list during a suggestion walk.
pub(crate) struct Cursor<'b> {
    list: &'b Bundled,
    next: usize,
}

impl Cursor<'_> {
    /// Index of the first word at or after `i` that shares fewer than `below`
    /// chars with its predecessor (`shared.len()` when there is none).
    fn skip(&self, mut i: usize, below: u8) -> usize {
        let shared = &self.list.shared;
        loop {
            // Word by word up to the end of the current block…
            let block_end = ((i / BLOCK + 1) * BLOCK).min(shared.len());
            while i < block_end && shared[i] >= below {
                i += 1;
            }
            if i < block_end || i >= shared.len() {
                return i;
            }
            // …then whole blocks at a time.
            let mut block = i / BLOCK;
            while self
                .list
                .block_min
                .get(block)
                .is_some_and(|&min| min >= below)
            {
                block += 1;
            }
            i = (block * BLOCK).min(shared.len());
        }
    }
}

impl WordSource<'static> for Cursor<'_> {
    fn next_below(&mut self, below: usize) -> Option<(usize, &'static str)> {
        let shared = &self.list.shared;
        let i = match u8::try_from(below) {
            Ok(below) => self.skip(self.next, below),
            Err(_) => self.next,
        };
        let start = *self.list.rest_start.get(i)? as usize;
        self.next = i + 1;
        Some((
            usize::from(shared[i]),
            &self.list.text[start..start + usize::from(self.list.rest_len[i])],
        ))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bundled_list_is_well_formed() {
        let words = bundled().words();
        assert!(words.len() > 300_000, "only {} words", words.len());
        assert_eq!(bundled().restarts.len(), words.len().div_ceil(RESTART));
        for pair in words.windows(2) {
            assert!(pair[0] < pair[1], "not strictly sorted: {:?}", pair);
        }
        for w in &words {
            assert!(
                (2..=MAX_WORD_LEN).contains(&w.len()) && w.bytes().all(|b| b.is_ascii_lowercase()),
                "bad word {w:?}"
            );
        }
        // The raw file agrees with the index: each line's shared length never
        // exceeds the previous word and every suffix is non-empty.
        let mut prev_len = 0;
        for (shared, suffix, _) in (Lines {
            text: WORDS,
            pos: 0,
        }) {
            assert!(shared <= prev_len && !suffix.is_empty());
            prev_len = shared + suffix.len();
        }
    }

    #[test]
    fn lookups_agree_with_the_decoded_list() {
        let b = bundled();
        let words = b.words();
        // Every word of a sample (including block boundaries) is found…
        for (i, w) in words.iter().enumerate().filter(|(i, _)| {
            i.is_multiple_of(97) || i.is_multiple_of(RESTART) || i % RESTART == RESTART - 1
        }) {
            assert!(b.contains(w), "word #{i} {w:?} not found");
        }
        assert!(b.contains(words.first().unwrap()));
        assert!(b.contains(words.last().unwrap()));
        // …and near misses are not.
        for w in words.iter().step_by(1009) {
            let mut miss = w.clone();
            miss.push('q');
            miss.push('q');
            if words.binary_search(&miss).is_err() {
                assert!(!b.contains(&miss), "{miss:?}");
            }
        }
        for w in [
            "",
            "a",
            "recieve",
            "teh",
            "zzzzzzzzzz",
            "Hello",
            "naïve",
            "abcdefghijklmnopqrstuvwxyz",
        ] {
            assert!(!b.contains(w), "{w:?}");
        }
        for w in [
            "receive",
            "the",
            "hello",
            "function",
            "parameter",
            "getcwd",
            "argv",
            "abspath",
        ] {
            assert!(b.contains(w), "{w:?}");
        }
    }

    #[test]
    fn cursor_skips_subtrees() {
        let b = bundled();
        let words = b.words();
        let mut cursor = b.cursor();
        let first = cursor.next_below(usize::MAX).unwrap();
        assert_eq!(first, (0, words[0].as_str()));
        // Skipping everything that shares the first letter lands on the
        // first word with another first letter.
        let (shared, rest) = cursor.next_below(1).unwrap();
        assert_eq!(shared, 0);
        let expected = words
            .iter()
            .find(|w| w.as_bytes()[0] != words[0].as_bytes()[0])
            .unwrap();
        assert_eq!(rest, expected);
        // Skipping past the end ends the walk.
        let mut cursor = b.cursor();
        assert!(cursor.next_below(0).is_none());
    }

    #[test]
    fn block_skips_agree_with_a_linear_scan() {
        let b = bundled();
        let cursor = b.cursor();
        let naive = |mut i: usize, below: u8| {
            while i < b.shared.len() && b.shared[i] >= below {
                i += 1;
            }
            i
        };
        let len = b.shared.len();
        let mut starts: Vec<usize> = (0..len).step_by(997).collect();
        starts.extend([
            0,
            BLOCK - 1,
            BLOCK,
            BLOCK + 1,
            len - BLOCK,
            len - 1,
            len,
            len + 3,
        ]);
        for start in starts {
            for below in 0..=12 {
                assert_eq!(
                    cursor.skip(start, below),
                    naive(start, below),
                    "start {start}, below {below}"
                );
            }
        }
    }

    #[test]
    fn lines_skip_blank_lines() {
        let text: &'static str = "0ab\n\n1c\n";
        let lines: Vec<(usize, &str, usize)> = (Lines { text, pos: 0 }).collect();
        assert_eq!(lines, vec![(0, "ab", 1), (1, "c", 6)]);
        let text: &'static str = "0ab\r\n\r\n1c";
        let lines: Vec<(usize, &str, usize)> = (Lines { text, pos: 0 }).collect();
        assert_eq!(lines, vec![(0, "ab", 1), (1, "c", 8)]);
        assert_eq!(prefix_len(b'A'), 10);
        assert_eq!(prefix_len(b'J'), 19);
    }

    #[test]
    fn crlf_line_ends_decode_like_lf() {
        // A checkout with `core.autocrlf` turns `words.txt` into CRLF text.
        let lf = Bundled::new("0abc\n3d\n2e\n0x\n");
        let crlf = Bundled::new("0abc\r\n3d\r\n2e\r\n0x\r\n");
        for list in [&lf, &crlf] {
            assert_eq!(list.words(), ["abc", "abcd", "abe", "x"]);
            for w in ["abc", "abcd", "abe", "x"] {
                assert!(list.contains(w), "{w}");
            }
            for w in ["ab", "abcde", "abd", "y", "abc\r"] {
                assert!(!list.contains(w), "{w:?}");
            }
        }
    }
}
